package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class UtilitiesActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Utility Infrastructure","Parcel-linked infrastructure references for service planning.");String u=getIntent().getStringExtra("ulpin");if(u==null)u="24-GJ-GN-0001-00001";DatabaseManager m=new DatabaseManager(this);Cursor c=m.getDatabase().rawQuery("SELECT utility_type,provider,connection_status,network_ref,last_verified FROM utilities WHERE ulpin=?",new String[]{u});try{if(c.moveToFirst())do{LinearLayout box=utils.column(this);utils.row(box,this,"Utility",c.getString(0));utils.row(box,this,"Provider",c.getString(1));utils.row(box,this,"Connection",c.getString(2));utils.row(box,this,"Network ref",c.getString(3));utils.row(box,this,"Verified",c.getString(4));utils.addCard(root,box,this);}while(c.moveToNext());else root.addView(utils.text(this,"No utility links in demo dataset.",14,utils.MUTED,false));}finally{c.close();}utils.setScreenContentView(this, root);}
}
